"""tools/procutil.py terminates every process it started (and their children) however the parent ends.

  procutil.py

A parent script starts a child through procutil, which itself starts a grandchild with plain subprocess. Both sleep. The parent
then ends in one of several ways and the test asserts that child and grandchild are gone afterwards.
"""
import os
import signal
import subprocess
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
TOOLS = os.path.join(HERE, "..", "..", "tools")
sys.path.insert(0, TOOLS)

SLEEP = "import time; time.sleep(600)"
CHILD = "import subprocess, sys, time; g = subprocess.Popen([sys.executable, '-c', %r]); print(g.pid, flush=True); time.sleep(600)" % SLEEP


def alive(pid):
    if os.name == "nt":
        import ctypes
        k32 = ctypes.windll.kernel32
        k32.OpenProcess.restype = ctypes.c_void_p
        handle = k32.OpenProcess(0x1000, False, pid)  # PROCESS_QUERY_LIMITED_INFORMATION
        if not handle:
            return False
        code = ctypes.c_ulong()
        k32.GetExitCodeProcess(ctypes.c_void_p(handle), ctypes.byref(code))
        k32.CloseHandle(ctypes.c_void_p(handle))
        return code.value == 259  # STILL_ACTIVE
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    try:  # a zombie that nobody reaped has already ended
        with open("/proc/%d/stat" % pid) as stat:
            return stat.read().rsplit(")", 1)[1].split()[0] != "Z"
    except OSError:
        return True


def wait_gone(pids, seconds=15):
    end = time.time() + seconds
    while time.time() < end:
        if not any(alive(pid) for pid in pids):
            return True
        time.sleep(0.1)
    return False


def parent(mode):
    """Runs in the script that is being ended."""
    import procutil
    child = procutil.Popen([sys.executable, "-c", CHILD], stdout=subprocess.PIPE, text=True)
    grandchild = int(child.stdout.readline())
    print(child.pid, grandchild, flush=True)
    if mode == "exception":
        raise RuntimeError("parent fails")
    if mode == "exit":
        return
    time.sleep(600)  # waits to be signaled or killed


def case(mode, ending):
    flags = subprocess.CREATE_NEW_PROCESS_GROUP if os.name == "nt" else 0
    process = subprocess.Popen([sys.executable, os.path.abspath(__file__), "parent", mode], stdout=subprocess.PIPE,
                               stderr=subprocess.DEVNULL, text=True, creationflags=flags)
    pids = [int(p) for p in process.stdout.readline().split()]
    if len(pids) != 2:
        return "%s: the parent did not report its children" % mode
    if ending == "kill":
        process.kill()
    elif ending == "terminate":
        process.terminate()
    elif ending == "interrupt":
        process.send_signal(signal.CTRL_BREAK_EVENT if os.name == "nt" else signal.SIGINT)
    try:
        process.wait(timeout=60)
    except subprocess.TimeoutExpired:
        process.kill()
        process.wait()
    if not wait_gone(pids):
        for pid in pids:
            if alive(pid):
                try:
                    os.kill(pid, signal.SIGTERM)
                except OSError:
                    pass
        return "%s (%s): the child %d or grandchild %d is still running" % (mode, ending, pids[0], pids[1])
    return None


def timeout_case():
    """procutil.run with a timeout must not leave the child or its grandchild behind."""
    sys.path.insert(0, TOOLS)
    import procutil
    marker = "procutil-test-%d" % os.getpid()
    code = "import subprocess, sys, time; subprocess.Popen([sys.executable, '-c', %r, %r]); time.sleep(600)" % ("import sys, time; time.sleep(600)", marker)
    started = time.time()
    try:
        procutil.run([sys.executable, "-c", code, marker], timeout=2)
        return "timeout: no TimeoutExpired"
    except subprocess.TimeoutExpired:
        pass
    if time.time() - started > 30:
        return "timeout: run() was blocked by the grandchild keeping the pipe open"
    return None


def main():
    if len(sys.argv) > 2 and sys.argv[1] == "parent":
        parent(sys.argv[2])
        return 0
    failures = []
    cases = [("exit", None), ("exception", None), ("sleep", "kill")]
    cases.append(("sleep", "interrupt"))
    if os.name != "nt":
        cases.append(("sleep", "terminate"))
    for mode, ending in cases:
        failure = case(mode, ending)
        print("%s/%s: %s" % (mode, ending, failure or "ok"))
        if failure:
            failures.append(failure)
    failure = timeout_case()
    print("timeout: %s" % (failure or "ok"))
    if failure:
        failures.append(failure)
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
